update template_items set ai_mode='suggest', ai_instructions='Look for evidence of core processes: the coach gives their own example before asking students (I do), does it together (we do) and then asks students to produce (you do); DPCQ or TPRS storytelling; explicit modeling. Energy, voice and body language cannot be seen: if only process evidence exists, return parcial with confidence media.' where item_number='D1' and template_id=(select id from templates where code='DMEP');
update template_items set ai_mode='suggest', ai_instructions='Count moments where the coach makes students repeat titles, corrections, instructions or examples ("everyone repeat", "let''s repeat"). Use the deterministic boosters count as support (2+ boosters = ok for Kids). Result si if repetition is constant and boosters >= 2; parcial if only one of the two.' where item_number='D2' and template_id=(select id from templates where code='DMEP');
update template_items set ai_mode='suggest', ai_instructions='Find student mistakes the coach corrects by modeling the correct form and asking for a retake ("one more time", "let''s repeat", "3 letters", "playing not play"). Look for at least two techniques (3 times, syllable breakdown, exaggeration, slow-fast, whiteboard, spotlight, translation contrast) and the sandwich pattern (praise, correction, praise). You cannot count every student mistake: judge whether corrections are consistent and structural (si), occasional (parcial) or absent (no). Quote 2-3 examples.' where item_number='D3' and template_id=(select id from templates where code='DMEP');
update template_items set ai_mode='suggest', ai_instructions='Look for how the coach handles microphones, cameras, distracted or off-task students and students speaking Spanish. Effective = the behavior stops or the student re-engages; repeated warnings with no change = parcial or no. Count warnings and quote the strongest ones.' where item_number='D4' and template_id=(select id from templates where code='DMEP');
update template_items set ai_mode='suggest', ai_instructions='Find a Mental Training moment: a block of affirmations repeated by students and/or a short motivational message from the coach (e.g. "every time we love what we do, we do it better"). Energy cannot be heard: if an MT block exists return si with confidence media; if only isolated affirmations, parcial; if none, no.' where item_number='M1' and template_id=(select id from templates where code='DMEP');
update template_items set ai_mode='auto' where item_number='M2' and template_id=(select id from templates where code='DMEP');
update template_items set ai_mode='suggest', ai_instructions='Find rapport: the coach asks students personal questions (weekend, food, movies, where are you from, new students) and reacts to the answers. For Adults look for FODO / follow-up time. Quote the questions with minute. si if 2+ students were asked something personal; parcial if only one; no if none.' where item_number='E1' and template_id=(select id from templates where code='DMEP');
update template_items set ai_mode='auto' where item_number='E2' and template_id=(select id from templates where code='DMEP');
update template_items set ai_mode='manual' where item_number='E3' and template_id=(select id from templates where code='DMEP');
update template_items set ai_mode='auto' where item_number in ('P1','P2','P4','P5') and template_id=(select id from templates where code='DMEP');
update template_items set ai_mode='suggest', ai_instructions='Within the AF window (given in deterministic.af_window) identify students who produced complete sentences appropriate to the level and whether the coach asked probing (why, where, when, tell me more) and spiral questions (about previous topics). Also look for comprehension checks (translation to Spanish, QA questions). si if 3+ students produced and checks exist; parcial if 3+ produced but no checks, or 2 produced with checks; no otherwise. Use deterministic.af_students as the base list and quote one sentence per student.' where item_number='P3' and template_id=(select id from templates where code='DMEP');
update template_items set ai_mode='auto' where kind='penalty' and description like '3. Too Much Spanish%' and template_id=(select id from templates where code='DMEP');
update template_items set ai_mode='auto' where kind='penalty' and description like '6. Timing%' and template_id=(select id from templates where code='DMEP');
update template_items set ai_mode='suggest', ai_instructions='Return si only if there is no booster or game at all in the whole transcript (use deterministic.boosters).' where kind='penalty' and description like '5. No Boosters%' and template_id=(select id from templates where code='DMEP');
update template_items set ai_mode='auto' where kind='bonus' and description like '8. 80/20%' and template_id=(select id from templates where code='DMEP');
update template_items set ai_mode='suggest', ai_instructions='Count coach questions pushing critical thinking: why?, what is your opinion?, what did you learn?, how did you feel?, what is your conclusion?, tell me more. si only if 5 or more with quotes.' where kind='bonus' and description like '7. BET/WELL%' and template_id=(select id from templates where code='DMEP');
update template_items set ai_mode='suggest', ai_instructions='Look for gamification: Wall of Fame, emojis, points, countries/trophies, Michidollars, competitions. si if used 3+ times with quotes.' where kind='bonus' and description like '5. GAME ON%' and template_id=(select id from templates where code='DMEP');